const newestUnreadItemPerFeed = `-- name: NewestUnreadItemPerFeed :many
SELECT f.id AS feed_id,
       CAST(COALESCE(MAX(strftime('%s', COALESCE(i.published_at, i.fetched_at))), 0) AS INTEGER) AS newest_sec
FROM feeds f
LEFT JOIN items i ON i.feed_id = f.id AND i.status = 'unread'
WHERE f.user_id = ?
GROUP BY f.id
`

type NewestUnreadItemPerFeedRow struct {
	FeedID    int64 `json:"feed_id"`
	NewestSec int64 `json:"newest_sec"`
}

func (q *Queries) NewestUnreadItemPerFeed(ctx context.Context, userID int64) ([]NewestUnreadItemPerFeedRow, error) {
	rows, err := q.db.QueryContext(ctx, newestUnreadItemPerFeed, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []NewestUnreadItemPerFeedRow{}
	for rows.Next() {
		var i NewestUnreadItemPerFeedRow
		if err := rows.Scan(&i.FeedID, &i.NewestSec); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rehomeFeedItems = `-- name: RehomeFeedItems :execrows
UPDATE items SET feed_id = ?1, updated_at = DATETIME('now')
WHERE feed_id = ?2
  AND (is_saved = 1 OR EXISTS (SELECT 1 FROM digest_result_items dri WHERE dri.item_id = items.id))
`

type RehomeFeedItemsParams struct {
	NewFeedID int64 `json:"new_feed_id"`
	OldFeedID int64 `json:"old_feed_id"`
}

// Moves a feed's kept items (saved or digest-linked) to its archive feed on
// deletion, preserving the original read state. The (feed_id, hash) unique
// index cannot collide: archive feeds start empty and receive rows once.
func (q *Queries) RehomeFeedItems(ctx context.Context, arg RehomeFeedItemsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, rehomeFeedItems, arg.NewFeedID, arg.OldFeedID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const setItemSaved = `-- name: SetItemSaved :one
UPDATE items
SET is_saved = ?1,
    status = CASE WHEN ?2 = 1 AND status = 'unread' THEN 'read' ELSE status END,
    updated_at = DATETIME('now')
WHERE id = ?3
RETURNING id, feed_id, hash, title, url, content, author, comment_url, points, comments_count, published_at, status, fetched_at, created_at, updated_at, last_enriched_at, extract_content, extract_status, extract_retries, extract_date, is_saved
`

type SetItemSavedParams struct {
	Saved    int64       `json:"saved"`
	MarkRead interface{} `json:"mark_read"`
	ID       int64       `json:"id"`
}

// Saved is orthogonal to read state: this touches ONLY is_saved, so a read
// toggle can never destroy saved-ness and vice versa. `saved = 1` also marks an
// unread item read (matching the pre-flag behaviour, where a saved item was not
// in the unread counts); unsaving clears the flag and leaves the read state
// alone, so an item that was already read stays read.
//
// mark_read carries the same value as saved. It is a second named parameter
// rather than a repeat of `saved` because a bare repeat inside the CASE would
// work in SQLite but leaves sqlc generating a positional Column2, and the
// duplication documents the rule: only the SAVE direction forces read.
func (q *Queries) SetItemSaved(ctx context.Context, arg SetItemSavedParams) (Item, error) {
	row := q.db.QueryRowContext(ctx, setItemSaved, arg.Saved, arg.MarkRead, arg.ID)
	var i Item
	err := row.Scan(
		&i.ID,
		&i.FeedID,
		&i.Hash,
		&i.Title,
		&i.Url,
		&i.Content,
		&i.Author,
		&i.CommentUrl,
		&i.Points,
		&i.CommentsCount,
		&i.PublishedAt,
		&i.Status,
		&i.FetchedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.LastEnrichedAt,
		&i.ExtractContent,
		&i.ExtractStatus,
		&i.ExtractRetries,
		&i.ExtractDate,
		&i.IsSaved,
	)
	return i, err
}

